	// buttons
	this.DoorHandle_mc = new lib.doorhandle();
	this.DoorHandle_mc.name = "DoorHandle_mc";
	this.DoorHandle_mc.setTransform(1089.8,831.4,1,1,0,0,0,-6.8,5.3);

	this.timeline.addTween(cjs.Tween.get(this.DoorHandle_mc).to({_off:true},1).wait(1));

	// text
	this.text = new cjs.Text("Open", "bold 75px 'Athelas'");
	this.text.textAlign = "center";
	this.text.lineHeight = 86;
	this.text.lineWidth = 262;
